SELECT COUNT(*) AS CustomerCount
FROM [sales].[Customers] AS c
WHERE c.[CountryCode] = 'PK';

SELECT
    SUM(CAST(oi.Quantity AS decimal(18,4)) * oi.UnitPrice) AS TotalGrossSales
FROM [sales].[OrderItems] AS oi;

SELECT COUNT(*) AS [OrdersWithoutSalesRep]
FROM [sales].[Orders] AS o
WHERE o.[SalesRepId] IS NULL;

SELECT SUM([p].[Amount]) AS [TotalAmountPaidUsingDigitalWallets]
FROM [sales].[Payments] AS [p]
WHERE [p].[Method] = 'Wallet';

SELECT COUNT(*) AS OrderLineCount
FROM [sales].[OrderItems] AS oi
WHERE oi.[DiscountPct] = 0.20;

SELECT COUNT(*) AS ReferredCustomerCount
FROM [sales].[Customers] AS c
WHERE c.[ReferredByCustomerId] IS NOT NULL;

SELECT COUNT(*) AS PendingOrderCount
FROM [sales].[Orders] AS o
WHERE o.[Status] = 'Pending';
